import{c as t,Q as r,j as a,m as o}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Financial Journey","description":"","frontmatter":{},"headers":[],"relativePath":"framework/journey.md","filePath":"framework/journey.md","lastUpdated":null}'),d={name:"framework/journey.md"};function n(s,e,i,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="financial-journey" tabindex="-1">Financial Journey <a class="header-anchor" href="#financial-journey" aria-label="Permalink to &quot;Financial Journey&quot;">​</a></h1><p>Seven milestones from stability to freedom — tracked against your ledger, with Copilot entry points at each stage.</p><table tabindex="0"><thead><tr><th>#</th><th>Milestone</th><th>Threshold (approx.)</th></tr></thead><tbody><tr><td>1</td><td>Stability</td><td>Bills paid, income tracked, categories set</td></tr><tr><td>2</td><td>Emergency buffer</td><td>1 month of expenses saved</td></tr><tr><td>3</td><td>Emergency fund</td><td>3–6 months saved</td></tr><tr><td>4</td><td>Debt free</td><td>Non-mortgage debt cleared (snowball)</td></tr><tr><td>5</td><td>On track</td><td>Savings rate ≥10% sustained; allocation healthy</td></tr><tr><td>6</td><td>Compounding</td><td>Goals funded; 10/20/30-year projection credible</td></tr><tr><td>7</td><td>Freedom</td><td>Investments + cash cover years of expenses; Behaviour &gt; math is the focus</td></tr></tbody></table><h2 id="how-progress-is-computed" tabindex="-1">How progress is computed <a class="header-anchor" href="#how-progress-is-computed" aria-label="Permalink to &quot;How progress is computed&quot;">​</a></h2><p>Journey reads the same <code>wellness_context</code> and goal/budget state as every other screen. A milestone unlocks when its thresholds are met against actual ledger data — the Copilot will not mark it complete on promises.</p><h2 id="using-journey" tabindex="-1">Using Journey <a class="header-anchor" href="#using-journey" aria-label="Permalink to &quot;Using Journey&quot;">​</a></h2><ul><li>Click a milestone to open the Copilot with a grounded prompt for that stage.</li><li>The progress reveal animates briefly and respects <code>prefers-reduced-motion</code>.</li><li>“More” holds secondary detail so primary milestones stay scannable.</li></ul><p>Journey is a map, not a scoreboard. The underlying math is exposed in the metric inspector whenever you want to check it.</p><p>See also: <a href="/FinSight/guide/journey">Guide → Journey</a>, <a href="/FinSight/framework/pay-yourself-first">Pay Yourself First</a>.</p>',9)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
